-- cafe (pending)
insert into quiz.assignments (slug, sort_order, is_active, title_sk, title_en, brief_sk, brief_en,
                              max_points, time_limit_ms, scenarios, design, reference_solution)
values ($q$cafe$q$, 90, true, $q$Objednávky v kaviarni$q$, $q$Cafe Orders$q$,
        ($q$"Malá kaviareň potrebuje jednoduchý konzolový systém, v ktorom si zákazník prezrie ponuku nápojov a dezertov a vytvorí si objednávku. Každý produkt v ponuke má názov a cenu. Kaviareň má jedno menu so všetkými produktmi. Objednávka patrí jednému zákazníkovi a obsahuje zoznam objednaných produktov a celkovú cenu.\n\nPri spustení je v menu týchto 5 produktov v tomto poradí: Espresso 2.00, Americano 2.80, Cappuccino 3.50, Latte 3.80 a Cheesecake 4.50. Ceny sa píšu s desatinnou bodkou a vždy s dvoma desatinnými miestami.\n\nZákazník sa najprv predstaví príkazom `name`, za ktorým nasleduje jeho meno. Program odpovie `Hello, Peter!` Toto meno sa potom použije pri objednávke.\n\nPríkaz `menu` vypíše všetky produkty, každý na samostatný riadok s poradovým číslom, názvom a cenou, napríklad `1. Espresso 2.00 EUR`. Príkaz `add`, za ktorým nasleduje názov a cena (napríklad Mocha a 4.20), pridá nový produkt na koniec menu a program odpovie `Mocha added to the menu.`\n\nPríkaz `find`, za ktorým nasleduje text, vypíše produkty, ktorých názov obsahuje tento text (veľkosť písmen nehrá rolu), napríklad `Americano 2.80 EUR`. Príkaz `cheaper`, za ktorým nasleduje suma, vypíše produkty, ktorých cena je nižšia ako zadaná suma, v rovnakom tvare. Ak sa nenájde žiadny produkt, oba príkazy vypíšu `No products found.` Produkty sa vždy vypisujú v poradí, v akom sú v menu.\n\nPríkaz `order`, za ktorým nasleduje názov produktu, pridá produkt do objednávky zákazníka a program odpovie `Cappuccino added to the order.` Ak taký produkt v menu nie je, odpovie `Product Mocha does not exist.` Príkaz `myorder` vypíše `Order for Peter:`, potom každý objednaný produkt na samostatný riadok (napríklad `Espresso 2.00 EUR`) v poradí objednania a nakoniec celkovú cenu, napríklad `Total: 10.00 EUR`. Ak je objednávka prázdna, vypíše iba `Your order is empty.`\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu s možnosťami, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"A small cafe needs a simple console system where a customer can look through the drinks and desserts on offer and place an order. Every product on offer has a name and a price. The cafe has one menu with all its products. An order belongs to one customer and holds the list of ordered products and the total price.\n\nWhen the program starts, the menu holds these 5 products in this order: Espresso 2.00, Americano 2.80, Cappuccino 3.50, Latte 3.80 and Cheesecake 4.50. Prices are written with a decimal point and always with two decimal places.\n\nFirst the customer introduces themselves with the command `name`, followed by their name. The program replies `Hello, Peter!` This name is then used for the order.\n\nThe command `menu` lists all products, each on its own line with its number, name and price, like `1. Espresso 2.00 EUR`. The command `add`, followed by a name and a price (for example Mocha and 4.20), adds a new product to the end of the menu, and the program replies `Mocha added to the menu.`\n\nThe command `find`, followed by some text, lists the products whose name contains that text (letter case does not matter), like `Americano 2.80 EUR`. The command `cheaper`, followed by an amount, lists the products whose price is lower than that amount, in the same form. If no product is found, both commands print `No products found.` Products are always listed in the order they are on the menu.\n\nThe command `order`, followed by a product name, adds that product to the customer's order and the program replies `Cappuccino added to the order.` If there is no such product on the menu, it replies `Product Mocha does not exist.` The command `myorder` prints `Order for Peter:`, then every ordered product on its own line (like `Espresso 2.00 EUR`) in the order they were ordered, and finally the total price, like `Total: 10.00 EUR`. If the order is empty, it prints only `Your order is empty.`\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu of options, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Výpis menu a pridanie produktu","name_en":"Listing the menu and adding a product","input":"name Peter\nmenu\nadd Mocha 4.20\nmenu\nexit\n","expected":"Hello, Peter!\n1. Espresso 2.00 EUR\n2. Americano 2.80 EUR\n3. Cappuccino 3.50 EUR\n4. Latte 3.80 EUR\n5. Cheesecake 4.50 EUR\nMocha added to the menu.\n1. Espresso 2.00 EUR\n2. Americano 2.80 EUR\n3. Cappuccino 3.50 EUR\n4. Latte 3.80 EUR\n5. Cheesecake 4.50 EUR\n6. Mocha 4.20 EUR\n","points":15},{"name_sk":"Vyhľadanie podľa názvu","name_en":"Searching by name","input":"name Peter\nfind ame\nfind CAKE\nfind tea\nexit\n","expected":"Hello, Peter!\nAmericano 2.80 EUR\nCheesecake 4.50 EUR\nNo products found.\n","points":25},{"name_sk":"Vyhľadanie podľa ceny","name_en":"Searching by price","input":"name Peter\ncheaper 3.50\ncheaper 2.00\nexit\n","expected":"Hello, Peter!\nEspresso 2.00 EUR\nAmericano 2.80 EUR\nNo products found.\n","points":20},{"name_sk":"Objednávka a celková cena sú presné","name_en":"The order and its total are exact","input":"name Peter\nmyorder\norder Espresso\norder Cappuccino\norder Cheesecake\nmyorder\nexit\n","expected":"Hello, Peter!\nYour order is empty.\nEspresso added to the order.\nCappuccino added to the order.\nCheesecake added to the order.\nOrder for Peter:\nEspresso 2.00 EUR\nCappuccino 3.50 EUR\nCheesecake 4.50 EUR\nTotal: 10.00 EUR\n","points":25},{"name_sk":"Objednanie neexistujúceho produktu zlyhá","name_en":"Ordering a product that does not exist fails","input":"name Peter\norder Mocha\nmyorder\nexit\n","expected":"Hello, Peter!\nProduct Mocha does not exist.\nYour order is empty.\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"Product","role":"item","properties":["string Name","decimal Price"]},{"name":"Order","role":"person","properties":["string CustomerName","List<Product> Products","decimal Total (sum of prices)"]},{"name":"Menu","role":"manager","properties":["string Name","List<Product> Products"],"operations":["AddProduct(product)","FindByName(text)","FindByMaxPrice(price)"]}],"link":"Order.Products → Product (one-way: the order knows its products)","storage":"List<Product> in Menu, List<Product> in Order"}$q$::jsonb,
        ($q$"// Reference solution – Cafe Orders. Hidden from students; used to validate the scenarios.\nusing System.Globalization;\n\nvar menu = new Menu(\"Kaviaren\");\nmenu.AddProduct(new Product(\"Espresso\", 2.00m));\nmenu.AddProduct(new Product(\"Americano\", 2.80m));\nmenu.AddProduct(new Product(\"Cappuccino\", 3.50m));\nmenu.AddProduct(new Product(\"Latte\", 3.80m));\nmenu.AddProduct(new Product(\"Cheesecake\", 4.50m));\n\nvar order = new Order(\"\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"name\")\n    {\n        order = new Order(parts[1]);\n        Console.WriteLine($\"Hello, {parts[1]}!\");\n    }\n    else if (command == \"menu\")\n    {\n        for (int i = 0; i < menu.Products.Count; i++)\n        {\n            Console.WriteLine($\"{i + 1}. {menu.Products[i].Info()}\");\n        }\n    }\n    else if (command == \"add\")\n    {\n        decimal price = decimal.Parse(parts[2], CultureInfo.InvariantCulture);\n        menu.AddProduct(new Product(parts[1], price));\n        Console.WriteLine($\"{parts[1]} added to the menu.\");\n    }\n    else if (command == \"find\")\n    {\n        PrintProducts(menu.FindByName(parts[1]));\n    }\n    else if (command == \"cheaper\")\n    {\n        PrintProducts(menu.FindByMaxPrice(decimal.Parse(parts[1], CultureInfo.InvariantCulture)));\n    }\n    else if (command == \"order\")\n    {\n        Product? product = menu.Find(parts[1]);\n        if (product == null)\n        {\n            Console.WriteLine($\"Product {parts[1]} does not exist.\");\n        }\n        else\n        {\n            order.Add(product);\n            Console.WriteLine($\"{product.Name} added to the order.\");\n        }\n    }\n    else if (command == \"myorder\")\n    {\n        order.Print();\n    }\n}\n\nstatic void PrintProducts(List<Product> products)\n{\n    if (products.Count == 0) Console.WriteLine(\"No products found.\");\n    foreach (Product product in products) Console.WriteLine(product.Info());\n}\n\nclass Product\n{\n    public string Name { get; }\n    public decimal Price { get; }\n\n    public Product(string name, decimal price)\n    {\n        Name = name;\n        Price = price;\n    }\n\n    public string Info()\n    {\n        return $\"{Name} {Price.ToString(\"0.00\", CultureInfo.InvariantCulture)} EUR\";\n    }\n}\n\nclass Order\n{\n    public string CustomerName { get; }\n    public List<Product> Products { get; } = new List<Product>();\n\n    public Order(string customerName)\n    {\n        CustomerName = customerName;\n    }\n\n    public decimal Total()\n    {\n        decimal total = 0;\n        foreach (Product product in Products) total += product.Price;\n        return total;\n    }\n\n    public void Add(Product product)\n    {\n        Products.Add(product);\n    }\n\n    public void Print()\n    {\n        if (Products.Count == 0)\n        {\n            Console.WriteLine(\"Your order is empty.\");\n            return;\n        }\n        Console.WriteLine($\"Order for {CustomerName}:\");\n        foreach (Product product in Products) Console.WriteLine(product.Info());\n        Console.WriteLine($\"Total: {Total().ToString(\"0.00\", CultureInfo.InvariantCulture)} EUR\");\n    }\n}\n\nclass Menu\n{\n    public string Name { get; }\n    public List<Product> Products { get; } = new List<Product>();\n\n    public Menu(string name)\n    {\n        Name = name;\n    }\n\n    public void AddProduct(Product product)\n    {\n        Products.Add(product);\n    }\n\n    public Product? Find(string name)\n    {\n        return Products.Find(p => p.Name.ToLower() == name.ToLower());\n    }\n\n    public List<Product> FindByName(string text)\n    {\n        return Products.FindAll(p => p.Name.ToLower().Contains(text.ToLower()));\n    }\n\n    public List<Product> FindByMaxPrice(decimal maxPrice)\n    {\n        return Products.FindAll(p => p.Price < maxPrice);\n    }\n}\n"$q$::jsonb #>> '{}'))
on conflict (slug) do update set
  sort_order = excluded.sort_order, is_active = excluded.is_active,
  title_sk = excluded.title_sk, title_en = excluded.title_en,
  brief_sk = excluded.brief_sk, brief_en = excluded.brief_en,
  max_points = excluded.max_points, time_limit_ms = excluded.time_limit_ms,
  scenarios = excluded.scenarios, design = excluded.design,
  reference_solution = excluded.reference_solution, updated_at = now();

commit;

-- check: imported assignments
select slug, is_active, title_en, jsonb_array_length(scenarios) as scenarios, max_points, updated_at
  from quiz.assignments order by sort_order, slug;
